contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether to c so that withdrawAll could change its balance.
    // amount and senderIsOwner are inputs: amount must be available in this contract's balance.
    function runTest(uint amount, bool senderIsOwner) public {
        require(address(this).balance >= amount);

        // Deposit Ether into c by calling its fallback: send value directly to c.
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        // Record balance before withdrawAll
        uint before = address(c).balance;

        // Decide who calls withdrawAll: if senderIsOwner true, this contract must be owner.
        // We cannot change c.owner here, so require that this contract's address equals c.owner() when senderIsOwner==true.
        // Use the public getter owner() and enforce consistency.
        if (senderIsOwner) {
            require(c.owner() == address(this));
            // call withdrawAll as owner
            c.withdrawAll();
        } else {
            require(c.owner() != address(this));
            // call withdrawAll as non-owner
            c.withdrawAll();
        }

        uint after = address(c).balance;

        // General rule: withdrawAll called by the tx sender does not decrease c.balance unless the sender is the owner.
        // Expressed as: if sender is not owner then after >= before
        assert(senderIsOwner || after >= before);
    }

    // allow receiving Ether for the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed: rule should hold for any caller
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On original contract, withdrawAll succeeds only when msg.sender == owner.
        // We cannot read owner, so express the rule: if the call did not revert then msg.sender must be the owner.
        // Since we cannot refer to owner directly, we instead assert that non-owners cannot succeed:
        // Use the public owner getter to observe ownership equality. It's allowed.
        address ownerAddr = c.owner();
        // If the call did not revert then the caller must equal owner; equivalently, if caller != owner then it must have reverted.
        assert((msg.sender != ownerAddr) ? reverted : true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No extra precondition needed: we state rule about caller identity
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // The rule: withdrawAll should revert if and only if msg.sender is not the owner.
        // We cannot read owner directly via c.owner() here as it's allowed (public getter), so use it.
        address owner = c.owner();
        // If caller is owner, call should not revert; if caller is not owner, call should revert.
        assert((msg.sender == owner && reverted == false) || (msg.sender != owner && reverted == true));
    }
    receive() external payable { }
}

