pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: the target address to forward funds to and an amount to send
    function testFuzz_property(address target, uint256 amount) public {
        // keep target non-zero to be admissible
        vm.assume(target != address(0));
        // bound amount to a reasonable range so vm.deal can handle it
        amount = bound(amount, 0, 1 ether);

        // Fund the test caller (owner) with the amount
        vm.deal(address(this), amount);

        // Owner (this contract) calls sendMoney on c forwarding value 'amount' to 'target'
        // sendMoney performs a low-level call _target.call{value: _value}("");
        // Use the fuzzed target as provided. If target is a plain EOA the call succeeds (no revert).
        // We call as the owner (setUp deployer is owner), so in the correct contract onlyOwner allows withdrawAll to be called by owner.

        // Perform the sendMoney as owner and forward ETH to the target via c
        vm.prank(address(this));
        c.sendMoney(target, amount);

        // After sendMoney completes, the owner can call withdrawAll which should withdraw the entire contract balance.
        // We call withdrawAll as the owner and then assert that the contract balance is zero.
        vm.prank(address(this));
        c.withdrawAll();

        // The universal property: after the owner calls withdrawAll the contract's balance must be zero.
        // This holds for the reference contract for all inputs; the mutant which inverts onlyOwner will prevent the owner
        // from withdrawing and so for some inputs the balance will be non-zero, causing this assertion to fail.
        assertTrue(address(c).balance == 0);
    }
}

