import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: target callee address selector will be the address of a deployed reverter,
    // and amount is fuzzed. We must NOT hard-code amounts/actors.
    function testFuzz_property(address caller, uint256 amount) public {
        // restrict caller to non-zero to be a valid EOA for vm.prank
        vm.assume(caller != address(0));
        // bound amount so it fits in practical test ETH budget but keep wide
        amount = bound(amount, 0, 1 ether);

        // deploy adversarial counterparty that ALWAYS reverts on calls
        Reverter r = new Reverter();

        // fund the contract c with some ether so sendMoney has balance to send
        vm.deal(address(this), 1 ether);
        // transfer into c
        payable(address(c)).transfer(0.5 ether);

        // record balance before
        uint256 before = address(c).balance;

        // make the call as the provided caller (EOA) and invoke sendMoney sending amount to the reverter
        vm.deal(caller, amount);
        vm.prank(caller);
        // call sendMoney on c; the low-level call from c to reverter will revert, but sendMoney does not check return
        // we wrap in try/catch to ensure we capture if c.sendMoney itself reverts (it shouldn't on reference)
        bool ok;
        try c.sendMoney(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After calling sendMoney to a reverting callee, the reference contract C should NOT have lost balance
        // (the low-level call reverted so funds remain in c). We assert that the balance stayed the same.
        // This single assertion is true for the reference for all admissible inputs, but the mutant that inverts onlyOwner
        // may allow unauthorized withdraws and thus can make the balance change for some inputs.
        assertTrue(address(c).balance == before);
    }
}

