pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker sends `amount` via sendMoney through a ReentrantHelper
    function testFuzz_property(uint256 amount, address attacker) public {
        // keep amount in a reasonable bound so vm.deal won't overflow and attacker != address(0)
        amount = bound(amount, 1, 1 ether);
        vm.assume(attacker != address(0));

        // deploy adversarial helper that will, when called, re-enter C to attempt withdrawAll
        ReentrantHelper helper = new ReentrantHelper(address(c));

        // fund contract C so there is a balance for withdrawal attempts
        vm.deal(address(c), 1 ether);

        // fund attacker so it can send value if needed (not strictly needed here but realistic)
        vm.deal(attacker, amount + 1 wei);

        // perform sendMoney from attacker to the helper, which on its fallback will call back into c
        vm.startPrank(attacker);
        // call sendMoney with value 'amount' forwarded to helper
        // note: sendMoney is non-payable in signature, but the target call is low-level; we attach value to C's call
        // so we call sendMoney and let it execute _target.call{value: _value}("") inside C
        c.sendMoney(address(helper), amount);
        vm.stopPrank();

        // After the interaction completes, the reference implementation ensures that C's balance is unchanged
        // because only the owner can withdraw; the mutant flips onlyOwner and may let the reentrant helper
        // (a non-owner) call withdrawAll and drain funds. We assert the reference property using address(c).balance.
        assertTrue(address(c).balance == 1 ether);
    }
}

// adversarial helper: on receiving funds via low-level call, it re-enters C by calling withdrawAll
contract ReentrantHelper {
    address immutable target;
    constructor(address _target) {
        target = _target;
    }
    fallback() external payable {
        // attempt to re-enter C and call withdrawAll as msg.sender = this contract (non-owner)
        // use low-level call to avoid revert bubbling
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        // ignore ok
        ok;
    }
}

