pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz on two parameters: an amount to fund the contract and a boolean that chooses whether the owner
    // routes received funds through an adversarial helper that reverts on receive. The helper must be a contract
    // because EOAs cannot revert on receive.
    function testFuzz_property(uint256 fundAmount, bool useReverter) public {
        // keep fundAmount in a reasonable wide range but non-zero to exercise transfer paths
        fundAmount = bound(fundAmount, 1, 1 ether);

        // deploy an adversarial helper that will be the owner's externally-owned fallback receiver if requested
        Reverter rev = new Reverter();

        // fund the contract c with fundAmount from an arbitrary external account
        address payer = address(0xBEEF);
        vm.deal(payer, fundAmount);
        vm.prank(payer);
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        // ensure caller is the owner (setUp made deployer msg.sender the owner). We simulate owner via prank.
        address owner = address(this); // test contract is the deployer in setUp
        // choose recipient: either a normal EOA or the reverter contract; if useReverter true, owner will be an address
        // that forwards received ETH into the reverter so that direct transfer to msg.sender could be blocked.
        // To simulate the attack where msg.sender's receive reverts, we make the owner be a contract that in its
        // receive() attempts to forward to the Reverter which reverts, causing the direct transfer to effectively fail.

        // Deploy a Forwarder owned by the test as the caller to c.withdrawAll; this Forwarder will be msg.sender for c
        // and its receive will forward to the Reverter if useReverter true, causing problems for direct transfer to msg.sender.
        Forwarder fwd = new Forwarder();
        // give forwarder some ETH so it can attempt to receive (not strictly necessary) but keep realism
        vm.deal(address(fwd), 0);

        // If useReverter, configure the Forwarder to forward incoming funds to the Reverter which reverts.
        if (useReverter) {
            fwd.setTarget(address(rev));
        } else {
            fwd.setTarget(address(0));
        }

        // Now call withdrawAll from the Forwarder (so msg.sender inside c is Forwarder). Forwarder will either accept funds
        // or have its receive revert when it forwards to the Reverter.
        // Make sure c has balance > 0
        assert(address(c).balance == fundAmount);

        vm.prank(address(fwd));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant for the reference: after calling withdrawAll as owner, c's balance is zero for ALL admissible inputs.
        // We assert that here. The buggy mutant will sometimes leave a non-zero balance for some inputs (useReverter==true)
        // because its direct transfer to msg.sender can be blocked by the reverter behavior routed through the owner.
        assertTrue(address(c).balance == 0);
    }
}

// Forwarder acts as the owner caller (msg.sender for c). It accepts ETH in receive and optionally forwards it to a target.
contract Forwarder {
    address public target;
    function setTarget(address _t) public { target = _t; }
    receive() external payable {
        if (target != address(0)) {
            // attempt to forward to a contract that may revert
            (bool ok,) = target.call{value: msg.value}("");
            require(ok, "forward failed");
        }
        // otherwise accept funds normally
    }
}

// Reverter always reverts on receive
contract Reverter {
    receive() external payable {
        revert("I always revert");
    }
}

