pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address 'ownerActor' (will act as owner) and an amount 'fund' to deposit
    function testFuzz_property(address ownerActor, uint256 fund) public {
        // restrict ownerActor to be non-zero and not the contract address
        vm.assume(ownerActor != address(0));
        vm.assume(ownerActor != address(c));
        // bound fund to a reasonable nonzero range (must allow zero? we care about >0)
        fund = bound(fund, 1, 1e30);

        // fund the owner externally so they can send Ether
        vm.deal(ownerActor, fund);

        // make ownerActor be the msg.sender for constructor-created owner: we cannot change c.owner after deployment,
        // so ensure ownerActor equals the original deployer by redeploying contract from ownerActor.
        // To do this, deploy a fresh C with ownerActor as deployer via vm.prank
        C localC;
        vm.prank(ownerActor);
        localC = new C();

        // send Ether to the contract so its fallback increments depositsCount and contract receives funds
        vm.prank(ownerActor);
        (bool sent,) = address(localC).call{value: fund}("");
        require(sent, "funding failed");

        // Sanity: contract has positive balance before withdrawAll
        assertTrue(address(localC).balance == fund);

        // ownerActor calls withdrawAll
        vm.prank(ownerActor);
        localC.withdrawAll();

        // GENERAL ASSERTION: for the correct contract, after withdrawAll the contract balance is zero.
        // The mutant that calls withdraw(0) will leave balance == fund, causing this assert to fail for some inputs.
        assertTrue(address(localC).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test driving c; params: amount to deposit then withdraw
    function runTest(uint depositAmount, uint withdrawAmount) public {
        // ensure this test contract has enough balance to fund the deposit
        require(address(this).balance >= depositAmount);

        // send depositAmount to c so its fallback increments depositsCount and increases balance
        (bool ok1, ) = address(c).call{value: depositAmount}("");
        require(ok1);

        // ensure caller is owner of c by design of the test environment (owner == test caller)
        // Now call withdraw as owner; on original P this uses transfer and will revert on failure,
        // but never performs a low-level call failure observable; on mutant M it uses call with ok returned.
        c.withdraw(withdrawAmount);

        // Observe whether c still has nonzero balance relation: after withdraw, c's balance should be
        // equal to depositAmount - withdrawAmount (or zero if over-withdrawn by transfer semantics would revert).
        // We assert that withdraw did not revert and that c's balance is less-or-equal to depositAmount.
        // This captures that withdraw succeeded (transfer would revert on failure but call might return false instead in M).
        assert(address(c).balance <= depositAmount);
    }

    // allow contract to receive ETH for funding deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address owner;
    constructor(C _c) { c = _c; owner = msg.sender; }
    function run(uint amount) public payable {
        require(true);
        bool reverted; try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        // As owner (constructor msg.sender deployed both contracts in the test harness), withdraw must not revert
        assert(reverted == false);
    }
    receive() external payable { }
}

