        // c2.owner is set to this test contract; we need owner to be rejecting. So deploy C from RejectingOwner via a factory call.
        // To make owner = rejecting, we deploy C by having RejectingOwner create it.
        C cOwned = rejecting.deployC();

        // fund cOwned so it has balance to withdraw
        vm.deal(address(this), depositAmount);
        // send ETH into the contract (fallback increments depositsCount but we just need balance)
        (bool ok, ) = address(cOwned).call{value: depositAmount}("0x");
        require(ok, "funding failed");

        // Now call sendMoney to an address that will revert on receive to simulate prior interaction
        RevertingReceiver rev = new RevertingReceiver();
        // send some small amount via sendMoney (owner must be the rejecting contract, but sendMoney is public and onlyOwner
        // so we must call sendMoney as owner. The owner of cOwned is rejecting contract, which deployed it, so only RejectingOwner can call.
