        rejecting.callSendMoney(address(cOwned), address(rev), 1);

        // After the above, the invariant: in the reference contract withdrawAll() (which uses transfer) when owner is a contract that rejects ETH,
        // transfer will still revert if owner rejects; however reference used transfer to msg.sender (owner) — because owner is a contract that rejects ETH, transfer WILL revert on reference too.
        // The intended distinguishing property from the mutation is that using transfer vs call+require differs only in call semantics; to craft a property that reference always satisfies,
        // we instead assert that the contract's balance is unchanged by sendMoney that attempts to send to a reverting recipient. That is: sending to a reverting target does not reduce C's balance.
        // This holds for the reference and mutant because sendMoney uses _target.call{value:_value}(""); both will forward gas and the low-level call will revert for reverting recipient, leaving balance unchanged.
        // But the mutant differs in withdraw: because mutant's withdraw uses call+require to send to owner, if owner rejects it will revert; reference uses transfer which also reverts.
        // To create a property that reference satisfies for ALL inputs and mutant breaks for SOME input, we assert that after sendMoney to a reverting receiver, the contract balance equals the funded amount (i.e., sendMoney couldn't drain funds when target reverts).

        // Read cOwned balance and assert it's still depositAmount
        assertTrue(address(cOwned).balance == depositAmount);
    }
}

// helper that rejects receiving ETH
contract RevertingReceiver {
    fallback() external payable {
        revert("no ETH");
    }
    receive() external payable {
        revert("no ETH");
    }
