// helper that will deploy a C with itself as creator (so it becomes owner) and can call sendMoney as owner
contract RejectingOwner {
    C public lastC;

    // deploy a new C; since this contract calls new C(), it becomes the owner
    function deployC() external returns (C) {
        C c = new C();
        lastC = c;
        return c;
    }

    // call sendMoney on a C we own
    function callSendMoney(address caddr, address target, uint256 value) external {
        C(caddr).sendMoney(target, value);
    }
}

